                // API Controller with IMAGE support
                file_put_contents(DIR_CATALOG . 'controller/api/pricepilot.php', '<?php
class ControllerApiPricepilot extends Controller {

    private function authenticate() {
        $token = isset($this->request->get[\'api_token\']) ? $this->request->get[\'api_token\'] : \'\';
        $stored_token = $this->config->get(\'module_pricepilot_token\');

        if (empty($token) || $token !== $stored_token) {
            $this->response->addHeader(\'HTTP/1.1 401 Unauthorized\');
            $this->response->addHeader(\'Content-Type: application/json\');
            $this->response->setOutput(json_encode([\'error\' => \'Invalid API token\']));
            return false;
        }
        return true;
    }

    public function index() {
        if (!$this->authenticate()) return;

        $this->load->model(\'catalog/product\');
        $this->load->model(\'tool/image\');

        $start = isset($this->request->get[\'start\']) ? (int)$this->request->get[\'start\'] : 0;
        $limit = isset($this->request->get[\'limit\']) ? (int)$this->request->get[\'limit\'] : 100;

        if ($limit > 1000) $limit = 1000;

        $filter_data = [
            \'start\' => $start,
            \'limit\' => $limit
        ];

        $products = $this->model_catalog_product->getProducts($filter_data);
        $total = $this->model_catalog_product->getTotalProducts();

        $json_products = [];
        foreach ($products as $product) {
            // Get manufacturer name
            $manufacturer = \'\';
            if ($product[\'manufacturer_id\']) {
                $manufacturer_info = $this->model_catalog_product->getManufacturer($product[\'manufacturer_id\']);
                if ($manufacturer_info) {
                    $manufacturer = $manufacturer_info[\'name\'];
                }
            }

            // Generate full image URL
            $image_url = null;
            if ($product[\'image\']) {
                if (method_exists($this->model_tool_image, \'resize\')) {
                    $image_url = $this->model_tool_image->resize($product[\'image\'], 500, 500);
                } else {
                    $image_url = HTTP_CATALOG . \'image/\' . $product[\'image\'];
                }
            }

            $json_products[] = [
                \'product_id\' => $product[\'product_id\'],
                \'name\' => $product[\'name\'],
                \'model\' => $product[\'model\'],
                \'sku\' => $product[\'sku\'],
                \'price\' => number_format((float)$product[\'price\'], 4, \'.\', \'\'),
                \'quantity\' => (int)$product[\'quantity\'],
                \'status\' => (int)$product[\'status\'],
                \'manufacturer\' => $manufacturer,
                \'manufacturer_id\' => (int)$product[\'manufacturer_id\'],
                \'image\' => $image_url
            ];
        }

        $this->response->addHeader(\'Content-Type: application/json\');
        $this->response->setOutput(json_encode([
            \'success\' => true,
            \'products\' => $json_products,
            \'total\' => $total,
            \'start\' => $start,
            \'limit\' => $limit
        ]));
    }

    public function update() {
        if (!$this->authenticate()) return;

        $json_input = file_get_contents(\'php://input\');
        $data = json_decode($json_input, true);

        if (!isset($data[\'product_id\']) || !isset($data[\'price\'])) {
            $this->response->addHeader(\'HTTP/1.1 400 Bad Request\');
            $this->response->addHeader(\'Content-Type: application/json\');
            $this->response->setOutput(json_encode([\'error\' => \'Missing product_id or price\']));
            return;
        }

        $product_id = (int)$data[\'product_id\'];
        $price = (float)$data[\'price\'];

        if ($price < 0) {
            $this->response->addHeader(\'HTTP/1.1 400 Bad Request\');
            $this->response->addHeader(\'Content-Type: application/json\');
            $this->response->setOutput(json_encode([\'error\' => \'Price must be non-negative\']));
            return;
        }

        // Get old price
        $this->load->model(\'catalog/product\');
        $product = $this->model_catalog_product->getProduct($product_id);

        if (!$product) {
            $this->response->addHeader(\'HTTP/1.1 404 Not Found\');
            $this->response->addHeader(\'Content-Type: application/json\');
            $this->response->setOutput(json_encode([\'error\' => \'Product not found\']));
            return;
        }

        $old_price = $product[\'price\'];

        // Update price
        $this->db->query("UPDATE " . DB_PREFIX . "product SET price = \'" . (float)$price . "\' WHERE product_id = \'" . (int)$product_id . "\'");

        $this->response->addHeader(\'Content-Type: application/json\');
        $this->response->setOutput(json_encode([
            \'success\' => true,
            \'message\' => \'Price updated successfully\',
            \'product_id\' => $product_id,
            \'old_price\' => number_format((float)$old_price, 4, \'.\', \'\'),
            \'new_price\' => number_format((float)$price, 4, \'.\', \'\')
        ]));
    }
}');

                // Mark setup as complete
                $this->load->model(\'setting/setting\');
                $settings = $this->model_setting_setting->getSetting(\'module_pricepilot\');
                $settings[\'module_pricepilot_version\'] = \'3.0.0\';
                $this->model_setting_setting->editSetting(\'module_pricepilot\', $settings);
            }

            // Grant permissions
            $this->load->model(\'user/user_group\');
            $this->model_user_user_group->addPermission($this->user->getGroupId(), \'access\', \'extension/module/pricepilot\');
            $this->model_user_user_group->addPermission($this->user->getGroupId(), \'modify\', \'extension/module/pricepilot\');

            // Add menu item
            $data[\'menus\'][] = array(
                \'id\'       => \'menu-pricepilot\',
                \'icon\'     => \'fa-bolt\',
                \'name\'     => \'PricePilot\',
                \'href\'     => $this->url->link(\'extension/module/pricepilot\', \'user_token=\' . $this->session->data[\'user_token\'], true),
                \'children\' => array()
            );
